          skullGrad.addColorStop(1, '#64748b');
          ctx.fillStyle = skullGrad;
          ctx.beginPath();
          ctx.ellipse(-0.3 * z, skullY, 5.8 * z, 6.2 * z, 0, 0, Math.PI * 2);
